import{_ as t,o,c as n,a0 as r}from"./chunks/framework.L_oL6aia.js";const h=JSON.parse('{"title":"2. Environment & Azure Setup","description":"","frontmatter":{},"headers":[],"relativePath":"setup-environment.md","filePath":"setup-environment.md"}'),i={name:"setup-environment.md"};function a(s,e,l,c,p,u){return o(),n("div",null,[...e[0]||(e[0]=[r('<h1 id="_2-environment-azure-setup" tabindex="-1">2. Environment &amp; Azure Setup <a class="header-anchor" href="#_2-environment-azure-setup" aria-label="Permalink to &quot;2. Environment &amp; Azure Setup&quot;">​</a></h1><p>Before writing any agent code, you must configure your development environment, provision resources in Azure, and deploy the base model. This section details how to get everything up and running.</p><hr><h2 id="_1-developer-environment-configuration" tabindex="-1">1. Developer Environment Configuration <a class="header-anchor" href="#_1-developer-environment-configuration" aria-label="Permalink to &quot;1. Developer Environment Configuration&quot;">​</a></h2><p>We use a consistent, pre-configured development environment. You can set this up locally or run it via <strong>GitHub Codespaces</strong>.</p><h3 id="environment-prerequisites" tabindex="-1">Environment Prerequisites <a class="header-anchor" href="#environment-prerequisites" aria-label="Permalink to &quot;Environment Prerequisites&quot;">​</a></h3><ul><li><strong>Python</strong>: Version <code>3.10</code> or higher (Python <code>3.13</code> is recommended).</li><li><strong>Azure CLI</strong>: Installed and available in your path (for terminal authentication).</li><li><strong>Core Dependencies</strong>: Installed via your package manager or pip:<div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">pip</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> install</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> azure-identity</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> azure-ai-projects</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> openai</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> python-dotenv</span></span></code></pre></div></li></ul><hr><h2 id="_2-microsoft-azure-provisioning" tabindex="-1">2. Microsoft Azure Provisioning <a class="header-anchor" href="#_2-microsoft-azure-provisioning" aria-label="Permalink to &quot;2. Microsoft Azure Provisioning&quot;">​</a></h2><p>To run AI agents, you need an active Azure subscription with access to the <strong>Microsoft AI Foundry Portal</strong>.</p><h3 id="step-by-step-resource-setup" tabindex="-1">Step-by-Step Resource Setup: <a class="header-anchor" href="#step-by-step-resource-setup" aria-label="Permalink to &quot;Step-by-Step Resource Setup:&quot;">​</a></h3><ol><li><p><strong>Sign in to Azure</strong>: Log in to the <a href="https://portal.azure.com" target="_blank" rel="noreferrer">Azure Portal</a>.</p></li><li><p><strong>Navigate to AI Foundry</strong>: Search for <strong>Microsoft Foundry</strong> or Azure AI Studio in the top search bar and navigate to the hub service.</p></li><li><p><strong>Create a Hub Resource</strong>:</p><ul><li>Click <strong>Create a resource</strong> in the top action bar.</li><li>Enter your resource details: <ul><li><strong>Subscription</strong>: Select the subscription provided/used for the workshop.</li><li><strong>Resource Group</strong>: Create a new group (e.g., <code>pizza-workshop-RG</code>).</li><li><strong>Resource Name</strong>: Give it a unique identifier (e.g., <code>pizza-foundry-resource-7yud</code>).</li><li><strong>Region</strong>: Choose <strong>East US</strong> or <strong>Sweden Central</strong> (where model deployments are fully available).</li><li><strong>Project Name</strong>: Enter <code>Pizza-Workshop</code>.</li></ul></li><li>Click <strong>Next</strong> through default networking/security tabs and hit <strong>Create</strong>. Deployment takes about 1–3 minutes.</li></ul></li><li><p><strong>Access the Project Hub</strong>:</p><ul><li>Navigate to <a href="https://ai.azure.com" target="_blank" rel="noreferrer">ai.azure.com</a> (Microsoft AI Foundry portal).</li><li>Locate and click your newly created <code>Pizza-Workshop</code> project.</li><li>Ensure the new modern AI Foundry interface is toggled ON.</li></ul></li></ol><hr><h2 id="_3-deploying-the-gpt-4o-model" tabindex="-1">3. Deploying the GPT-4o Model <a class="header-anchor" href="#_3-deploying-the-gpt-4o-model" aria-label="Permalink to &quot;3. Deploying the GPT-4o Model&quot;">​</a></h2><p>AI Agent Service leverages deployed LLM endpoints within your project context.</p><ol><li><strong>Deploy Model</strong>: In the left sidebar of the AI Foundry portal under your project, go to <strong>Build</strong> &gt; <strong>Models</strong> and click <strong>Deploy a base model</strong>.</li><li><strong>Choose Model</strong>: Select the <strong>gpt-4o</strong> model from the catalog list and click <strong>Deploy</strong>.</li><li><strong>Deployment Settings</strong>: Keep the default deployment configurations, naming the deployment <code>gpt-4o</code> (or match your preferred environment variable definition).</li><li><strong>Test in Playground</strong>: Go to the <strong>Model Playground</strong> once deployment is active, type &quot;Hello world&quot;, and verify that you receive a structured response from the model.</li></ol><hr><h2 id="_4-local-environment-configuration" tabindex="-1">4. Local Environment Configuration <a class="header-anchor" href="#_4-local-environment-configuration" aria-label="Permalink to &quot;4. Local Environment Configuration&quot;">​</a></h2><p>To allow your Python code to securely authenticate and connect to your Azure resources:</p><h3 id="step-1-create-a-env-file" tabindex="-1">Step 1: Create a <code>.env</code> File <a class="header-anchor" href="#step-1-create-a-env-file" aria-label="Permalink to &quot;Step 1: Create a `.env` File&quot;">​</a></h3><p>Create a <code>.env</code> file in the root of your project directory (the same folder containing your python scripts) and add these variables:</p><div class="language-env vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">env</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>PROJECT_ENDPOINT=&quot;https://&lt;your-foundry-resource&gt;.services.ai.azure.com/api/projects/&lt;your-project-name&gt;&quot;</span></span>\n<span class="line"><span>MODEL_DEPLOYMENT_NAME=&quot;gpt-4o&quot;</span></span></code></pre></div><div class="note custom-block github-alert"><p class="custom-block-title">NOTE</p><p>Make sure there are no trailing spaces or spaces around the <code>=</code> character in the <code>.env</code> file. Replace the project endpoint URL with the actual value from your Azure AI Foundry project dashboard overview.</p></div><h3 id="step-2-authenticate-via-azure-cli" tabindex="-1">Step 2: Authenticate via Azure CLI <a class="header-anchor" href="#step-2-authenticate-via-azure-cli" aria-label="Permalink to &quot;Step 2: Authenticate via Azure CLI&quot;">​</a></h3><p>The Azure Identity SDK uses <code>DefaultAzureCredential</code> to fetch local authentication tokens. Authenticate your terminal session by executing:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">az</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> login</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --use-device-code</span></span></code></pre></div><p>Follow the interactive device login flow in your browser. Once complete, your Python scripts will automatically detect your Azure identity and authenticate requests to the AI Project Client.</p>',27)])])}const g=t(i,[["render",a]]);export{h as __pageData,g as default};
